 "content": "def transform(grid):
    """For a partial row of a non-background color, replace background cells with 1."""
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    color = next((v for row in grid for v in row if v != background), background)
    for row in out:
        if row.count(background) and row.count(color):
            for j, value in enumerate(row):
                if value == background:
                    row[j] = 1
    return out
